import { randomUUID } from "node:crypto";

export type HotFileWriteOwner = {
  ownerId: string;
  claimedAt: number;
};

export type HotFileWriteClaim =
  | {
      ok: true;
      path: string;
      ownerId: string;
      token: string;
      claimedAt: number;
      reentrant: boolean;
    }
  | {
      ok: false;
      path: string;
      ownerId: string;
      conflict: true;
      holder: HotFileWriteOwner;
    };

export type HotFileWriteRelease =
  | { ok: true; released: true; path: string; ownerId: string }
  | { ok: true; released: false; path: string; ownerId: string; reason: "not-owner" | "token-mismatch" | "not-claimed" }
  | { ok: false; path: string; ownerId: string; conflict: true; holder: HotFileWriteOwner };

type ClaimRecord = {
  owner: HotFileWriteOwner;
  token: string;
};

export type HotFileWriteConflictError = Error & {
  code: "HOT_FILE_WRITE_CONFLICT";
  path: string;
  requestedOwnerId: string;
  holder: HotFileWriteOwner;
};

export function isHotFileWriteConflictError(
  error: unknown,
): error is HotFileWriteConflictError {
  return error instanceof Error && error.name === "HotFileWriteConflictError";
}

/**
 * A small, process-local ownership index. It deliberately does not schedule work:
 * serialization remains the responsibility of the existing fileMutation queue.
 * All claim and release transitions are synchronous, so a claim is atomic within
 * the JavaScript process.
 */
export class HotFileWriteOwnerRegistry {
  private readonly claims = new Map<string, ClaimRecord>();
  private readonly runDepth = new Map<string, number>();

  claim(path: string, ownerId: string): HotFileWriteClaim {
    const existing = this.claims.get(path);
    if (existing) {
      if (existing.owner.ownerId === ownerId) {
        return {
          ok: true,
          path,
          ownerId,
          token: existing.token,
          claimedAt: existing.owner.claimedAt,
          reentrant: true,
        };
      }

      return {
        ok: false,
        path,
        ownerId,
        conflict: true,
        holder: { ...existing.owner },
      };
    }

    const claimedAt = Date.now();
    const token = randomUUID();
    this.claims.set(path, {
      owner: { ownerId, claimedAt },
      token,
    });

    return {
      ok: true,
      path,
      ownerId,
      token,
      claimedAt,
      reentrant: false,
    };
  }

  release(path: string, ownerId: string, token: string): HotFileWriteRelease {
    const existing = this.claims.get(path);
    if (!existing) {
      return { ok: true, released: false, path, ownerId, reason: "not-claimed" };
    }
    if (existing.owner.ownerId !== ownerId) {
      return {
        ok: false,
        path,
        ownerId,
        conflict: true,
        holder: { ...existing.owner },
      };
    }
    if (existing.token !== token) {
      return { ok: true, released: false, path, ownerId, reason: "token-mismatch" };
    }

    this.claims.delete(path);
    this.runDepth.delete(path);
    return { ok: true, released: true, path, ownerId };
  }

  holder(path: string): HotFileWriteOwner | undefined {
    const existing = this.claims.get(path);
    return existing ? { ...existing.owner } : undefined;
  }

  /**
   * Runs a write under an ownership claim and under the caller's existing
   * fileMutation lease. The lease callback must serialize mutations for the same
   * canonical path; this class never creates a queue or scheduler.
   */
  async run<T>(options: {
    path: string;
    ownerId: string;
    queueLease: <R>(path: string, operation: () => Promise<R>) => Promise<R>;
    write: () => Promise<T>;
  }): Promise<T> {
    const { path, ownerId, queueLease, write } = options;
    const claim = this.claim(path, ownerId);
    if (!claim.ok) {
      throw this.conflictError(claim);
    }

    const depth = this.runDepth.get(path) ?? 0;
    this.runDepth.set(path, depth + 1);

    try {
      return await queueLease(path, write);
    } finally {
      const nextDepth = (this.runDepth.get(path) ?? 1) - 1;
      if (nextDepth > 0) {
        this.runDepth.set(path, nextDepth);
      } else {
        this.runDepth.delete(path);
        this.release(path, ownerId, claim.token);
      }
    }
  }

  private conflictError(claim: Extract<HotFileWriteClaim, { ok: false }>): HotFileWriteConflictError {
    const error = new Error(
      `Hot file ${claim.path} is owned by ${claim.holder.ownerId}; requested owner ${claim.ownerId}`,
    ) as HotFileWriteConflictError;
    error.name = "HotFileWriteConflictError";
    error.code = "HOT_FILE_WRITE_CONFLICT";
    error.path = claim.path;
    error.requestedOwnerId = claim.ownerId;
    error.holder = claim.holder;
    return error;
  }
}

export const hotFileWriteOwnerRegistry = new HotFileWriteOwnerRegistry();

export function runHotFileWrite<T>(options: {
  registry?: HotFileWriteOwnerRegistry;
  path: string;
  ownerId: string;
  queueLease: <R>(path: string, operation: () => Promise<R>) => Promise<R>;
  write: () => Promise<T>;
}): Promise<T> {
  const registry = options.registry ?? hotFileWriteOwnerRegistry;
  return registry.run({
    path: options.path,
    ownerId: options.ownerId,
    queueLease: options.queueLease,
    write: options.write,
  });
}

