    const existing = this.claims.get(path);
    if (existing) {
      if (existing.owner.ownerId === ownerId) {
        return {
          ok: true,
          path,
          ownerId,
          token: existing.token,
          claimedAt: existing.owner.claimedAt,
          reentrant: true,
        };
      }

      return {
        ok: false,
        path,
        ownerId,
        conflict: true,
        holder: { ...existing.owner },
      };
    }

    const claimedAt = Date.now();
    const token = randomUUID();
    this.claims.set(path, {
      owner: { ownerId, claimedAt },
      token,
    });

    return {
      ok: true,
      path,
      ownerId,
      token,
      claimedAt,
      reentrant: false,
    };
  }

  release(path: string, ownerId: string, token: string): HotFileWriteRelease {
    const existing = this.claims.get(path);
    if (!existing) {
      return { ok: true, released: false, path, ownerId, reason: "not-claimed" };
    }
    if (existing.owner.ownerId !== ownerId) {
      return {
        ok: false,
        path,
        ownerId,
        conflict: true,
        holder: { ...existing.owner },
      };
    }
    if (existing.token !== token) {
      return { ok: true, released: false, path, ownerId, reason: "token-mismatch" };
    }

    this.claims.delete(path);
    this.runDepth.delete(path);
    return { ok: true, released: true, path, ownerId };
  }

