    const claim = this.claim(path, ownerId);
    if (!claim.ok) {
      throw this.conflictError(claim);
    }

    const depth = this.runDepth.get(path) ?? 0;
    this.runDepth.set(path, depth + 1);

    try {
      return await queueLease(path, write);
    } finally {
      const nextDepth = (this.runDepth.get(path) ?? 1) - 1;
      if (nextDepth > 0) {
        this.runDepth.set(path, nextDepth);
      } else {
        this.runDepth.delete(path);
        this.release(path, ownerId, claim.token);
      }
    }
